  duetName_window: ["隔窗应答", "Window Reply"], duetName_moon: ["月灯巡岸", "Moon Patrol"], duetName_star: ["星灯巡岸", "Star Patrol"], duetName_echo: ["星灯短句", "Star Echo"], duetName_round: ["两岸回旋", "Harbour Round"],
  duetClue_free: ["试着改变谁先启程。空闲时，信就在菱印多等几拍。", "Try changing which letter leads. A letter can wait at the desk before setting out."],
  duetClue_window: ["菱印紧挨两只信箱。试着让两封信都只走一格。", "Both boxes adjoin the desk. Give each letter a one-cell trip."],
  duetClue_moon: ["月信想去岸边兜一圈，星信想从近窗进站。想想谁该先走。", "Send the moon around the shore and the star to its nearest window."],
  duetClue_star: ["让星信绕远岸回家，月信留在菱印旁的近窗。", "Let the star take the long shore route. The moon stays by its window."],
  duetClue_echo: ["月信走近窗。替星信找一段三格的小弯。", "Use the near window for the moon. Find a three-cell bend for the star."],
  duetClue_round: ["沿着两岸各绕一圈，再让两声回信同时响起。", "Take both letters around the shore and let their replies ring together."],
  duetStory_window: ["窗与窗之间只隔一格水。你才按灯，我的窗纸就亮了。", "Only one stretch of water lies between our windows. I see the light as soon as you press the key."],
  duetStory_moon: ["我绕去看了那艘旧渡船。回来时，你的灯刚好点亮。", "I swung past the old ferry. Your light came on just as I returned."],
  duetStory_star: ["你把星灯一路举过堤岸，我在最近的窗边等最后一拍。", "You carried the star along the seawall. I waited at the near window for the final beat."],
  duetStory_echo: ["你的信只拐了一个小弯，带回来一声很短的回音。", "Your letter took a little bend and brought back a brief echo."],
  duetStory_round: ["我们各走一岸，隔着水绕回原处。两扇窗像同时眨了一下眼。", "We went round opposite shores. On the last beat, both windows blinked."],
  duetCoda: ["值班簿最后一页写着两行字。一行是你的，一行是我的，最后那个句点落在同一拍。", "The log ends with two lines, one yours and one mine. Their full stops fall on the same beat."],
  duetMode_relaxed: ["原图起步更近，逐步提示会优先寻找未寄出的灯谱。", "A gentler start with guidance toward an unfiled score."],
